# name: balance_pref_matched_alternation
# description: Among pairs of irregular sequences (both alternation rates >= 0.5) whose alternation rates differ by at most 1/7 but whose H/T imbalance differs, the proportion choosing the more balanced sequence; observed above the null means the model under-predicts a preference for balanced H/T counts that alternation alone cannot capture.

def _alt(s):
    return sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1)

def _imb(s):
    return abs(s.count("H") - len(s) / 2.0) / len(s)

def _maxrun(s):
    best = cur = 1
    for x, y in zip(s, s[1:]):
        cur = cur + 1 if x == y else 1
        best = max(best, cur)
    return best

def _feat(col, f):
    u = pd.unique(col)
    return col.map({s: f(s) for s in u}).to_numpy(dtype=float)

def test_statistic(df):
    aa = _feat(df["sequence_a"], _alt); ab = _feat(df["sequence_b"], _alt)
    ia = _feat(df["sequence_a"], _imb); ib = _feat(df["sequence_b"], _imb)
    y = df["chose_left"].to_numpy(dtype=float)
    m = (aa >= 0.5) & (ab >= 0.5) & (np.abs(aa - ab) <= 1/7 + 1e-9) & (np.abs(ia - ib) > 1e-9)
    if m.sum() == 0:
        return 0.5
    left_more_balanced = ia[m] < ib[m]
    chose_bal = np.where(left_more_balanced, y[m], 1 - y[m])
    return float(chose_bal.mean())

# name: maxrun_effect_beyond_alternation
# description: Among pairs where both sequences have alternation rate >= 0.5, the coefficient on (longest run of right minus longest run of left) in a linear-probability regression of chose_left on [1, alt_left - alt_right, maxrun_right - maxrun_left]; observed above the null means people penalise long runs beyond what the alternation rate captures, which the model under-predicts.

def _alt(s):
    return sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1)

def _imb(s):
    return abs(s.count("H") - len(s) / 2.0) / len(s)

def _maxrun(s):
    best = cur = 1
    for x, y in zip(s, s[1:]):
        cur = cur + 1 if x == y else 1
        best = max(best, cur)
    return best

def _feat(col, f):
    u = pd.unique(col)
    return col.map({s: f(s) for s in u}).to_numpy(dtype=float)

def test_statistic(df):
    aa = _feat(df["sequence_a"], _alt); ab = _feat(df["sequence_b"], _alt)
    ra = _feat(df["sequence_a"], _maxrun); rb = _feat(df["sequence_b"], _maxrun)
    y = df["chose_left"].to_numpy(dtype=float)
    m = (aa >= 0.5) & (ab >= 0.5)
    if m.sum() < 5:
        return 0.0
    X = np.column_stack([np.ones(m.sum()), aa[m] - ab[m], rb[m] - ra[m]])
    coef, *_ = np.linalg.lstsq(X, y[m], rcond=None)
    return float(coef[2])

# name: left_choice_rate
# description: Overall proportion of trials on which the left sequence was chosen; observed above the null (about 0.5 given randomised sides) means the model misses a left-side response bias.
def test_statistic(df):
    return float(df["chose_left"].astype(float).mean())

# name: one_switch_vs_constant
# description: Among pairs where one sequence is constant (0 alternations) and the other has exactly one switch, the proportion choosing the one-switch sequence; observed above the model's null means the model under-predicts how strongly people reject all-same sequences.

def _alt(s):
    return sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1)

def _imb(s):
    return abs(s.count("H") - len(s) / 2.0) / len(s)

def _maxrun(s):
    best = cur = 1
    for x, y in zip(s, s[1:]):
        cur = cur + 1 if x == y else 1
        best = max(best, cur)
    return best

def _feat(col, f):
    u = pd.unique(col)
    return col.map({s: f(s) for s in u}).to_numpy(dtype=float)

def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    na = _feat(a, lambda s: sum(x != y for x, y in zip(s, s[1:])))
    nb = _feat(b, lambda s: sum(x != y for x, y in zip(s, s[1:])))
    y = df["chose_left"].to_numpy(dtype=float)
    m1 = (na == 1) & (nb == 0); m2 = (na == 0) & (nb == 1)
    n = m1.sum() + m2.sum()
    if n == 0:
        return 0.5
    return float((y[m1].sum() + (1 - y[m2]).sum()) / n)

# name: short_vs_long_alt_pref_gap
# description: Rate of choosing the higher-alternation sequence (pairs with alternation difference >= 0.25) on short sequences (length <= 7) minus the same rate on length-8 sequences; a discrepancy from the null means the model mis-predicts how alternation preference changes with sequence length (positive observed-minus-null = people prefer alternation more on short sequences than the model predicts).

def _alt(s):
    return sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1)

def _imb(s):
    return abs(s.count("H") - len(s) / 2.0) / len(s)

def _maxrun(s):
    best = cur = 1
    for x, y in zip(s, s[1:]):
        cur = cur + 1 if x == y else 1
        best = max(best, cur)
    return best

def _feat(col, f):
    u = pd.unique(col)
    return col.map({s: f(s) for s in u}).to_numpy(dtype=float)

def test_statistic(df):
    aa = _feat(df["sequence_a"], _alt); ab = _feat(df["sequence_b"], _alt)
    L = df["sequence_a"].str.len().to_numpy()
    y = df["chose_left"].to_numpy(dtype=float)
    m = np.abs(aa - ab) >= 0.25
    ch = np.where(aa > ab, y, 1 - y)
    s = m & (L <= 7); l = m & (L == 8)
    if s.sum() == 0 or l.sum() == 0:
        return 0.0
    return float(ch[s].mean() - ch[l].mean())

# name: side_repetition_rate
# description: Proportion of consecutive trials (within participant, ordered by trial_index) on which the participant chose the same side as on the previous trial; observed above the null means the model misses response perseveration, below means a side-alternation habit.
def test_statistic(df):
    d = df.sort_values(["participant_id", "trial_index"])
    pid = d["participant_id"].to_numpy(); y = d["chose_left"].to_numpy()
    same_p = pid[1:] == pid[:-1]
    if same_p.sum() == 0:
        return 0.5
    return float((y[1:] == y[:-1])[same_p].mean())

# name: perfect_alternation_choice
# description: Among pairs where exactly one sequence is perfectly alternating (alternation rate 1) and the other is streaky (alternation rate <= 2/7, e.g. HTHTHTHT vs HHHHHHHT), the proportion choosing the perfect alternator; observed above the null means the model under-predicts the population-level preference for perfect alternation over streaks (its split of personal ideals makes it too indifferent), below means it over-predicts it.

def _alt(s):
    return sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1)

def _imb(s):
    return abs(s.count("H") - len(s) / 2.0) / len(s)

def _maxrun(s):
    best = cur = 1
    for x, y in zip(s, s[1:]):
        cur = cur + 1 if x == y else 1
        best = max(best, cur)
    return best

def _feat(col, f):
    u = pd.unique(col)
    return col.map({s: f(s) for s in u}).to_numpy(dtype=float)

def test_statistic(df):
    aa = _feat(df["sequence_a"], _alt); ab = _feat(df["sequence_b"], _alt)
    y = df["chose_left"].to_numpy(dtype=float)
    m1 = (aa == 1) & (ab <= 2/7 + 1e-9)
    m2 = (ab == 1) & (aa <= 2/7 + 1e-9)
    n = m1.sum() + m2.sum()
    if n == 0:
        return 0.5
    return float((y[m1].sum() + (1 - y[m2]).sum()) / n)

# name: participant_spread_alt_pref
# description: Across participants, the standard deviation of each person's rate of choosing the higher-alternation sequence on pairs whose alternation rates differ by >= 0.25; observed below the null means the model over-produces individual differences in ideal alternation rate (people are more homogeneous than it assumes), above means under-produces.

def _alt(s):
    return sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1)

def _imb(s):
    return abs(s.count("H") - len(s) / 2.0) / len(s)

def _maxrun(s):
    best = cur = 1
    for x, y in zip(s, s[1:]):
        cur = cur + 1 if x == y else 1
        best = max(best, cur)
    return best

def _feat(col, f):
    u = pd.unique(col)
    return col.map({s: f(s) for s in u}).to_numpy(dtype=float)

def test_statistic(df):
    aa = _feat(df["sequence_a"], _alt); ab = _feat(df["sequence_b"], _alt)
    y = df["chose_left"].to_numpy(dtype=float)
    m = np.abs(aa - ab) >= 0.25
    ch = np.where(aa > ab, y, 1 - y)
    s = pd.Series(ch[m]).groupby(df["participant_id"].to_numpy()[m]).mean()
    if len(s) < 2:
        return 0.0
    return float(s.std(ddof=1))
